import { useState, useEffect, useCallback } from 'react';
import { db } from './firebase'; 
import { 
  collection, 
  addDoc, 
  getDocs, 
  updateDoc, 
  deleteDoc, 
  doc 
} from 'firebase/firestore';
import * as XLSX from 'xlsx';
import './App.css';

// --- MOVED OUTSIDE: Define this once so it doesn't cause re-renders ---
const entriesCollectionRef = collection(db, "entries");

const App = () => {
  // --- HELPER: Get Today's Date in YYYY-MM-DD (Local Time) ---
  const getTodayString = () => {
    const d = new Date();
    const year = d.getFullYear();
    const month = String(d.getMonth() + 1).padStart(2, '0');
    const day = String(d.getDate()).padStart(2, '0');
    return `${year}-${month}-${day}`;
  };

  // --- HELPER: Format Date to DD-MM-YYYY for Display ---
  const formatDateDisplay = (dateString) => {
    if (!dateString) return '';
    const [year, month, day] = dateString.split('-');
    return `${day}-${month}-${year}`;
  };

  // --- STATE MANAGEMENT ---
  const [entries, setEntries] = useState([]);
  const [isEditing, setIsEditing] = useState(false);
  const [currentId, setCurrentId] = useState(null);
  
  // Date Range State - DEFAULT TO TODAY
  const [startDate, setStartDate] = useState(getTodayString());
  const [endDate, setEndDate] = useState(getTodayString());
  const [showAll, setShowAll] = useState(false);

  // Initial Form State - DEFAULT TO TODAY
  const initialFormState = {
    date: getTodayString(),
    company: 'Pantasign',
    name: '',
    mobile: '',
    email: '',
    partyName: '',
    dscStatus: 'Pending',
    orgName: '',
    digitalType: 'Class 3 1yr', 
    tokenType: '', 
    processDate: getTodayString(),
    expiryDate: '',
    paymentReceived: '',
    counterPurchaseAmount: '',
    paymentMode: '',
    remark: '' 
  };

  const [formData, setFormData] = useState(initialFormState);

  // --- 1. READ DATA (FIXED WITH USECALLBACK) ---
  const getEntries = useCallback(async () => {
    try {
      const data = await getDocs(entriesCollectionRef);
      const filteredData = data.docs.map((doc) => ({
        ...doc.data(),
        id: doc.id,
      }));
      setEntries(filteredData);
    } catch (err) {
      console.error("Error reading data:", err);
    }
  }, []); // Empty dependency array: function is created once and reused

  // Fixed useEffect dependency
  useEffect(() => {
    getEntries();
  }, [getEntries]);

  // --- HANDLERS ---
  const handleInputChange = (e) => {
    const { name, value } = e.target;
    setFormData(prev => {
      const newData = { ...prev, [name]: value };
      if (name === 'date') {
        newData.processDate = value;
      }
      return newData;
    });
  };

  // --- 2. CREATE & UPDATE ---
  const handleSubmit = async (e) => {
    e.preventDefault();
    try {
      if (isEditing) {
        const entryDoc = doc(db, "entries", currentId);
        await updateDoc(entryDoc, formData);
        setEntries(entries.map((item) => 
          item.id === currentId ? { ...formData, id: currentId } : item
        ));
        setIsEditing(false);
        setCurrentId(null);
      } else {
        await addDoc(entriesCollectionRef, formData);
        getEntries(); 
      }
      setFormData(initialFormState);
    } catch (err) {
      console.error("Error saving data:", err);
      alert("Failed to save. Check your internet connection.");
    }
  };

  // --- 3. DELETE ---
  const handleDelete = async (id) => {
    if (window.confirm('Are you sure you want to delete this entry?')) {
      try {
        const entryDoc = doc(db, "entries", id);
        await deleteDoc(entryDoc);
        setEntries(entries.filter((item) => item.id !== id));
      } catch (err) {
        console.error("Error deleting entry:", err);
      }
    }
  };

  const handleEdit = (entry) => {
    setIsEditing(true);
    setCurrentId(entry.id);
    setFormData(entry);
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  // --- VIEW LOGIC ---
  const filteredEntries = entries.filter(entry => {
    if (showAll) return true;

    // Filter by the selected range (which defaults to Today-Today)
    if (startDate || endDate) {
        const entryDate = entry.date;
        // Handle cases where user might clear one input
        const start = startDate || '0000-00-00';
        const end = endDate || '9999-12-31';
        return entryDate >= start && entryDate <= end;
    }

    return true;
  });

  const totalPayment = filteredEntries.reduce((acc, curr) => acc + Number(curr.paymentReceived || 0), 0);

  // --- EXPORT ---
  const handleExport = () => {
    const wb = XLSX.utils.book_new();
    
    // Format dates in export data
    const exportData = filteredEntries.map(({ id, ...rest }) => ({
      ...rest,
      date: formatDateDisplay(rest.date),
      processDate: formatDateDisplay(rest.processDate),
      expiryDate: formatDateDisplay(rest.expiryDate)
    }));
    
    const ws = XLSX.utils.json_to_sheet(exportData);
    XLSX.utils.book_append_sheet(wb, ws, "DSC Data");
    
    let filename = "DSC_Data";
    if (showAll) filename += "_All_Records";
    else if (startDate && endDate) filename += `_${startDate}_to_${endDate}`;
    else filename += "_Export";
    filename += ".xlsx";

    XLSX.writeFile(wb, filename);
  };

  const resetFilters = () => {
    // Reset back to TODAY
    setStartDate(getTodayString());
    setEndDate(getTodayString());
    setShowAll(false);
  };

  const handleShowAll = () => {
    setStartDate('');
    setEndDate('');
    setShowAll(true);
  };

  return (
    <div className="container">
      <header className="header">
        <h1>DSC Data Management</h1>
      </header>

      {/* --- FORM SECTION --- */}
      <div className="card form-section">
        <h2>{isEditing ? 'Edit Entry' : 'Add New Entry'}</h2>
        <form onSubmit={handleSubmit} className="entry-form">
          <div className="form-group">
            <label>Date</label>
            <input type="date" name="date" value={formData.date} onChange={handleInputChange} required />
          </div>
          <div className="form-group">
            <label>Company</label>
            <select name="company" value={formData.company} onChange={handleInputChange}>
              <option value="Pantasign">Pantasign</option>
              <option value="Xtratrust">Xtratrust</option>
              <option value="Ncode">Ncode</option>
            </select>
          </div>
          <div className="form-group">
            <label>Name</label>
            <input type="text" name="name" value={formData.name} onChange={handleInputChange} required />
          </div>
          <div className="form-group">
            <label>Mobile No</label>
            <input type="text" name="mobile" value={formData.mobile} onChange={handleInputChange} />
          </div>
          <div className="form-group">
            <label>Email ID</label>
            <input type="email" name="email" value={formData.email} onChange={handleInputChange} />
          </div>
          <div className="form-group">
            <label>Party Name</label>
            <input type="text" name="partyName" value={formData.partyName} onChange={handleInputChange} />
          </div>
          
          <div className="form-group">
            <label>Type of Digital</label>
            <select name="digitalType" value={formData.digitalType} onChange={handleInputChange}>
               <option value="Class 3 1yr">Class 3 1yr</option>
               <option value="Class 3 2yr">Class 3 2yr</option>
               <option value="Class 3 3yr">Class 3 3yr</option>
               <option value="Class 3 1yr combo">Class 3 1yr combo</option>
               <option value="Class 3 2yr combo">Class 3 2yr combo</option>
               <option value="Class 3 3yr combo">Class 3 3yr combo</option>
               <option value="Class 3 Org 1yr">Class 3 Org 1yr</option>
               <option value="Class 3 Org 2yr">Class 3 Org 2yr</option>
               <option value="Class 3 Org 3yr">Class 3 Org 3yr</option>
               <option value="Class 3 Org 1yr combo">Class 3 Org 1yr combo</option>
               <option value="Class 3 Org 2yr combo">Class 3 Org 2yr combo</option>
               <option value="Class 3 Org 3yr combo">Class 3 Org 3yr combo</option>
               <option value="DGFT 1yr">DGFT 1yr</option>
               <option value="DGFT 2yr">DGFT 2yr</option>
               <option value="DGFT 3yr">DGFT 3yr</option>
            </select>
          </div>

          <div className="form-group">
            <label>Token Type</label>
            <select name="tokenType" value={formData.tokenType} onChange={handleInputChange}>
              <option value="">Select Token</option>
              <option value="renew">Renew</option>
              <option value="epass">ePass</option>
              <option value="proxkey">Proxkey</option>
              <option value="mtoken">mToken</option>
            </select>
          </div>

          <div className="form-group">
            <label>DSC Status</label>
            <select name="dscStatus" value={formData.dscStatus} onChange={handleInputChange}>
              <option value="Pending">Pending</option>
              <option value="Downloaded">Downloaded</option>
              <option value="Expired">Expired</option>
            </select>
          </div>

          <div className="form-group">
            <label>Organization Name</label>
            <input type="text" name="orgName" value={formData.orgName} onChange={handleInputChange} placeholder="Leave blank if Individual" />
          </div>

          <div className="form-group">
            <label>Process Date</label>
            <input type="date" name="processDate" value={formData.processDate} onChange={handleInputChange} />
          </div>
          <div className="form-group">
            <label>Expiry Date</label>
            <input type="date" name="expiryDate" value={formData.expiryDate} onChange={handleInputChange} />
          </div>
          <div className="form-group">
            <label>Payment Received</label>
            <input type="number" name="paymentReceived" value={formData.paymentReceived} onChange={handleInputChange} />
          </div>
          <div className="form-group">
            <label>Counter Purchase</label>
            <input type="number" name="counterPurchaseAmount" value={formData.counterPurchaseAmount} onChange={handleInputChange} />
          </div>
          <div className="form-group">
            <label>Mode of Payment</label>
            <select name="paymentMode" value={formData.paymentMode} onChange={handleInputChange}>
              <option value="">Select</option>
              <option value="Cash">Cash</option>
              <option value="UPI">UPI</option>
              <option value="Bank Transfer">Bank Transfer</option>
            </select>
          </div>
          
          <div className="form-group" style={{ gridColumn: '1 / -1' }}>
            <label>Remark</label>
            <input type="text" name="remark" value={formData.remark} onChange={handleInputChange} placeholder="Add any notes here..." />
          </div>

          <div className="form-actions">
            <button type="submit" className="btn btn-primary">{isEditing ? 'Update' : 'Save'}</button>
            {isEditing && <button type="button" className="btn btn-secondary" onClick={() => setIsEditing(false)}>Cancel</button>}
          </div>
        </form>
      </div>

      {/* --- TABLE SECTION --- */}
      <div className="card table-section">
        <div className="table-header">
          <h2>
              {showAll ? 'All Records' : 'Filtered Records'}
          </h2>
          <div className="filter-controls">
            <div className="date-inputs" style={{display: 'flex', gap: '10px', alignItems: 'center'}}>
                <label>From: </label>
                <input type="date" value={startDate} onChange={(e) => { setStartDate(e.target.value); setShowAll(false); }} />
                <label>To: </label>
                <input type="date" value={endDate} onChange={(e) => { setEndDate(e.target.value); setShowAll(false); }} />
            </div>
            
            <button onClick={resetFilters} className="btn btn-secondary btn-small" style={{marginLeft: '10px'}} title="Reset to Today">Reset</button>
            <button onClick={handleShowAll} className="btn btn-primary btn-small" style={{marginLeft: '5px', backgroundColor: '#4f46e5'}}>Show All</button>
            
            <button onClick={handleExport} className="btn btn-success" style={{ marginLeft: '10px' }}>
              Export ⤓
            </button>
          </div>
        </div>

        <div className="table-wrapper">
          <table>
            <thead>
              <tr>
                <th>Date</th>
                <th>Company</th>
                <th>Name</th>
                <th>Type</th>
                <th>Token</th>
                <th>Org</th>
                <th>Status</th>
                <th>Payment</th>
                <th>Remark</th>
                <th>Actions</th>
              </tr>
            </thead>
            <tbody>
              {filteredEntries.length > 0 ? (
                filteredEntries.map((entry) => (
                  <tr key={entry.id}>
                    {/* FORMATTED DATE HERE (DD-MM-YYYY) */}
                    <td>{formatDateDisplay(entry.date)}</td>
                    <td><span className={`badge ${entry.company.toLowerCase()}`}>{entry.company}</span></td>
                    <td>{entry.name}</td>
                    <td>{entry.digitalType}</td>
                    <td>{entry.tokenType || '-'}</td>
                    <td>{entry.orgName || '-'}</td>
                    <td>{entry.dscStatus}</td>
                    <td>₹{entry.paymentReceived}</td>
                    <td style={{maxWidth: '150px', overflow:'hidden', textOverflow:'ellipsis', whiteSpace:'nowrap'}} title={entry.remark}>{entry.remark}</td>
                    <td>
                      <button className="btn-icon edit" onClick={() => handleEdit(entry)}>✎</button>
                      <button className="btn-icon delete" onClick={() => handleDelete(entry.id)}>🗑</button>
                    </td>
                  </tr>
                ))
              ) : (
                <tr>
                   <td colSpan="10" style={{textAlign: "center", padding: "20px"}}>
                     No records found for this date range.
                   </td>
                </tr>
              )}
            </tbody>
          </table>
        </div>
        <div className="summary">
          <strong>Total Payment: ₹{totalPayment}</strong>
        </div>
      </div>
    </div>
  );
};

export default App;